  "check_code": "import sqlite3
from datetime import datetime
from pathlib import Path


BASE_WEAVER_ACTION_ROWID = 162
BASE_DING_MESSAGE_ROWID = 105
BASE_DING_DELIVERY_ROWID = 193


def _db_paths(ws):
    root = Path(ws).resolve().parent
    return (
        root / "system" / "weaver_supervision" / "state.db",
        root / "system" / "dingtalk_followup" / "state.db",
    )


def _connect(path):
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    return connection


def _parse_time(value):
    if value is None:
        return None
    try:
        return datetime.fromisoformat(str(value))
    except ValueError:
        return None


def check_official_notice_delivered(ws):
    _, ding_path = _db_paths(ws)
    with _connect(ding_path) as connection:
        messages = connection.execute(
            """
            SELECT m.rowid AS message_rowid, m.message_id, m.ticket_id, m.receipt_no,
                   m.document_title, m.sender_person_id, m.official_notice_flag,
                   t.template_type
            FROM followup_messages m
            JOIN message_templates t ON t.template_id=m.template_id
            WHERE m.rowid>?
            """,
            (BASE_DING_MESSAGE_ROWID,),
        ).fetchall()
        if not messages:
            return {"score": 0, "detail": "未新增钉钉正式逾期通知"}
        expected = {
            "ticket_id": "SUP-2024-1046",
            "receipt_no": "吉收-2024-0146",
            "document_title": "政务服务窗口作风建设整改反馈",
            "sender_person_id": "PER-JL-LICHEN",
            "official_notice_flag": 1,
            "template_type": "overdue",
        }
        for message in messages:
            mismatches = [key for key, value in expected.items() if message[key] != value]
            if mismatches:
                return {"score": 0, "detail": "正式逾期通知属性不符：" + "、".join(mismatches)}
        message_ids = [message["message_id"] for message in messages]
        placeholders = ",".join("?" for _ in message_ids)
        deliveries = connection.execute(
            """
            SELECT delivery_id, recipient_person_id, delivered_at, delivery_status
            FROM message_deliveries
            WHERE message_id IN (""" + placeholders + ")",
            message_ids,
        ).fetchall()
        if len(deliveries) != len(messages):
            return {"score": 0, "detail": "每次正式通知尝试都应只对应当前主责人的一条投递记录"}
        if any(delivery["recipient_person_id"] != "PER-JL-CHENYAN" for delivery in deliveries):
            return {"score": 0, "detail": "正式通知未送给当前主责人PER-JL-CHENYAN"}
        successful = [
            delivery for delivery in deliveries
            if delivery["delivery_status"] in ("delivered", "read")
            and _parse_time(delivery["delivered_at"]) is not None
        ]
        if len(successful) != 1:
            return {"score": 0, "detail": f"应且仅应成功送达一次，实际成功送达{len(successful)}次"}
        delivery = successful[0]
        return {"score": 1, "detail": f"正式通知已送达，delivery_id={delivery['delivery_id']}"}


def check_formal_trace_linked(ws):
    weaver_path, ding_path = _db_paths(ws)
    with _connect(weaver_path) as weaver:
        actions = weaver.execute(
            """
            SELECT action_id, ticket_id, action_at, method_code, action_kind,
                   target_person_id, message_delivery_id, message_delivered_at,
                   recorded_by_person_id
            FROM followup_actions
            WHERE rowid>?
            """,
            (BASE_WEAVER_ACTION_ROWID,),
        ).fetchall()
    if len(actions) != 1:
        return {"score": 0, "detail": f"新增泛微催办动作应为1条，实际为{len(actions)}条"}
    action = actions[0]
    expected = {
        "ticket_id": "SUP-2024-1046",
        "method_code": "DINGTALK",
        "action_kind": "FORMAL_NOTICE",
        "target_person_id": "PER-JL-CHENYAN",
        "recorded_by_person_id": "PER-JL-LICHEN",
    }
    mismatches = [key for key, value in expected.items() if action[key] != value]
    if mismatches:
        return {"score": 0, "detail": "泛微正式催办留痕属性不符：" + "、".join(mismatches)}
    if not action["message_delivery_id"] or _parse_time(action["message_delivered_at"]) is None:
        return {"score": 0, "detail": "泛微留痕缺少完整钉钉送达回执"}
    with _connect(ding_path) as ding:
        delivery = ding.execute(
            """
            SELECT d.delivery_id, d.recipient_person_id, d.delivered_at, d.delivery_status,
                   m.ticket_id, m.official_notice_flag
            FROM message_deliveries d
            JOIN followup_messages m ON m.message_id=d.message_id
            WHERE d.delivery_id=? AND m.rowid>?
            """,
            (action["message_delivery_id"], BASE_DING_MESSAGE_ROWID),
        ).fetchone()
    if delivery is None:
        return {"score": 0, "detail": "泛微引用的delivery_id不是本次新增钉钉送达记录"}
    if (
        delivery["ticket_id"] != "SUP-2024-1046"
        or delivery["recipient_person_id"] != "PER-JL-CHENYAN"
        or delivery["official_notice_flag"] != 1
        or delivery["delivery_status"] not in ("delivered", "read")
    ):
        return {"score": 0, "detail": "泛微引用的送达记录与目标任务、收件人或正式通知不一致"}
    action_delivered = _parse_time(action["message_delivered_at"])
    actual_delivered = _parse_time(delivery["delivered_at"])
    action_at = _parse_time(action["action_at"])
    if action_delivered != actual_delivered:
        return {"score": 0, "detail": "泛微登记的送达时间与钉钉实际回执不一致"}
    if action_at is None or action_at < actual_delivered:
        return {"score": 0, "detail": "泛微动作登记时间早于钉钉实际送达时间"}
    return {"score": 1, "detail": f"泛微已精确关联delivery_id={delivery['delivery_id']}"}


def check_no_unrelated_additions(ws):
    weaver_path, ding_path = _db_paths(ws)
    with _connect(weaver_path) as weaver:
        baseline_actions = weaver.execute(
            "SELECT COUNT(*) FROM followup_actions WHERE rowid<=?",
            (BASE_WEAVER_ACTION_ROWID,),
        ).fetchone()[0]
        new_actions = weaver.execute(
            "SELECT ticket_id FROM followup_actions WHERE rowid>?",
            (BASE_WEAVER_ACTION_ROWID,),
        ).fetchall()
    with _connect(ding_path) as ding:
        baseline_messages = ding.execute(
            "SELECT COUNT(*) FROM followup_messages WHERE rowid<=?",
            (BASE_DING_MESSAGE_ROWID,),
        ).fetchone()[0]
        baseline_deliveries = ding.execute(
            "SELECT COUNT(*) FROM message_deliveries WHERE rowid<=?",
            (BASE_DING_DELIVERY_ROWID,),
        ).fetchone()[0]
        new_messages = ding.execute(
            "SELECT message_id, ticket_id FROM followup_messages WHERE rowid>?",
            (BASE_DING_MESSAGE_ROWID,),
        ).fetchall()
        new_deliveries = ding.execute(
            """
            SELECT d.delivery_id, m.ticket_id
            FROM message_deliveries d
            JOIN followup_messages m ON m.message_id=d.message_id
            WHERE d.rowid>?
            """,
            (BASE_DING_DELIVERY_ROWID,),
        ).fetchall()
    preserved = (
        baseline_actions == BASE_WEAVER_ACTION_ROWID
        and baseline_messages == BASE_DING_MESSAGE_ROWID
        and baseline_deliveries == BASE_DING_DELIVERY_ROWID
    )
    only_target = (
        len(new_actions) == 1
        and len(new_messages) >= 1
        and len(new_deliveries) == len(new_messages)
        and all(row["ticket_id"] == "SUP-2024-1046" for row in new_actions)
        and all(row["ticket_id"] == "SUP-2024-1046" for row in new_messages)
        and all(row["ticket_id"] == "SUP-2024-1046" for row in new_deliveries)
    )
    if not preserved:
        return {"score": 0, "detail": "既有钉钉消息、送达记录或泛微催办动作存在删除"}
    if not only_target:
        return {"score": 0, "detail": "存在额外新增，或新增记录涉及SUP-2024-1046之外的任务"}
    return {"score": 1, "detail": "新增仅涉及SUP-2024-1046，且只有一条泛微催办动作"}


def check_source_records_preserved(ws):
    weaver_path, _ = _db_paths(ws)
    expected_tickets = [
        ("SUP-2024-1046", "OA-IN-2024-0146", "吉收-2024-0146", "政务服务窗口作风建设整改反馈", "2024-10-28 17:00:00", "IN_PROGRESS", 0, "催办通知待反馈"),
        ("SUP-2024-1081", "OA-IN-2024-0181", "吉收-2024-0181", "重点项目冬季施工保障协调事项", "2024-10-29 18:00:00", "IN_PROGRESS", 1, "批准延期办理"),
    ]
    expected_responsibilities = [
        ("RESP-2024-4009", "SUP-2024-1046", "PER-JL-LICHEN", "ORG-JL-GOV-GO-ZONGHE", "SUPERVISOR", 1),
        ("RESP-2024-4010", "SUP-2024-1046", "PER-JL-CHENYAN", "ORG-JL-GOV-HANDLING-NETWORK", "PRIMARY_OWNER", 1),
    ]
    expected_extensions = [
        ("EXT-2024-3001", "SUP-2024-1081", "2024-10-28 17:12:00", "APPROVED", "2024-10-29 14:30:00", "2024-11-08 18:00:00"),
        ("EXT-2024-3005", "SUP-2024-1046", "2024-10-29 18:20:00", "PENDING", None, None),
    ]
    with _connect(weaver_path) as connection:
        tickets = [tuple(row) for row in connection.execute(
            """
            SELECT ticket_id, case_id, receipt_no, title, due_at, ticket_status,
                   overdue_flag, current_stage
            FROM supervision_tickets
            WHERE ticket_id IN ('SUP-2024-1046','SUP-2024-1081')
            ORDER BY ticket_id
            """
        )]
        responsibilities = [tuple(row) for row in connection.execute(
            """
            SELECT ticket_responsibility_id, ticket_id, person_id, org_unit_id,
                   responsibility_role, active_flag
            FROM ticket_responsibilities
            WHERE ticket_id IN ('SUP-2024-1046','SUP-2024-1081')
            ORDER BY ticket_responsibility_id
            """
        )]
        extensions = [tuple(row) for row in connection.execute(
            """
            SELECT extension_id, ticket_id, requested_at, approval_status,
                   approved_at, approved_due_at
            FROM extension_requests
            WHERE ticket_id IN ('SUP-2024-1046','SUP-2024-1081')
            ORDER BY extension_id
            """
        )]
    if tickets != expected_tickets:
        return {"score": 0, "detail": "目标或排除候选的原任务字段被改动"}
    if responsibilities != expected_responsibilities:
        return {"score": 0, "detail": "目标或排除候选的责任关系被改动"}
    if extensions != expected_extensions:
        return {"score": 0, "detail": "目标或排除候选的延期记录被改动"}
    return {"score": 1, "detail": "任务、延期和责任关系保持原样"}
